import{at as e,it as t,n,vt as r}from"./chunks/framework.fhiXEbOi.js";var i=JSON.parse(`{"title":"Contract-defined workflows","description":"Understand, try, use, build or deploy contract-defined workflows.","frontmatter":{"title":"Contract-defined workflows","description":"Understand, try, use, build or deploy contract-defined workflows.","outline":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="contract-defined-workflows" tabindex="-1">Contract-defined workflows <a class="header-anchor" href="#contract-defined-workflows" aria-label="Permalink to “Contract-defined workflows”">​</a></h1><div class="ported-guide"><p>A contract publishes a workflow description. A generic viewer or agent interprets it; business contracts enforce the rules. Start with the task you need—not with deployment internals.</p><p class="lede"><a href="./gallery/">Explore the Gallery</a> to open published apps directly in the stand-alone viewer or Pages preview.</p><section id="documentation"><div class="grid two"><section class="card"><h2><a href="./gallery/">Gallery</a></h2><p><a href="./gallery/">Browse deployed apps</a>, choose the latest or an earlier release, and open the selected instance.</p></section><section class="card"><h2><a href="./start/">Start</a></h2><p>Understand <a href="./start/">what runs where</a>, then <a href="./start/local-wallet.html">try Pay-to-Play with a local test wallet</a>.</p></section><section class="card"><h2><a href="./use/">Use</a></h2><p>Open a published app through the <a href="./gallery/">Gallery</a>, or <a href="./use/">enter the CAM host of an unlisted app</a>.</p></section><section class="card"><h2><a href="./build/">Build</a></h2><p><a href="./build/">Edit and validate a workflow</a>, or <a href="./build/headless.html">integrate without a browser</a>. Begin with <a href="./build/setup.html">source setup</a>.</p></section><section class="card"><h2><a href="./deploy/">Deploy</a></h2><p><a href="./deploy/viewer.html">Host the stand-alone viewer</a>, <a href="./deploy/new-instance.html">deploy a new app</a>, or <a href="./deploy/update.html">update an existing publication</a>. These are different tasks.</p></section><section class="card"><h2><a href="./reference/cam/">Reference</a></h2><p><a href="./reference/cam/1.4.0/">CAM 1.4.0 / UI 1.1.0</a>, with precise resource, route and execution rules. Older specifications are historical.</p></section></div></section><section id="apps"><h2>App guides</h2><p><a href="./use/pay-to-play/">Pay-to-Play</a>: voucher payments and balance recovery. <a href="./use/escrow/">Escrow</a>: agreements and settlement. <a href="./use/bike-nft/">Bike NFT</a>: components and ownership.</p><p>These are guides rather than live apps. <a href="./gallery/">Open published applications in the Gallery</a>, or use the <a href="./start/examples/#local-demos">demo selector</a> for a disposable local app.</p></section><section id="try"><h2>Try it before deploying</h2><p>The <a href="./start/local-wallet.html">local-wallet tutorial</a> runs a fresh chain and test accounts, takes you through a deposit, and shows what to stop. It does not use your real wallet.</p></section><section id="development"><h2>Development setup</h2><p><a href="./build/setup.html">Install locked dependencies, select a local Docker engine and choose the relevant checks</a>. The source and documentation branches have separate owners and validation paths.</p></section><p id="problem"><span id="approach"></span>Need the system explanation? <a href="./start/">Follow one read and one transaction across browser, hosted files, RPC and contracts</a>.</p><p id="status"><span id="roadmap"></span>Current format support and historical references are listed in the <a href="./reference/cam/">reference index</a>. A working fixture does not qualify a public deployment.</p><p id="related">For protocol boundaries and related implementation evidence, use the <a href="./reference/cam/1.4.0/#provenance">current reference&#39;s provenance section</a>.</p><p id="archive">The <a href="https://github.com/numpde/dapp32/tree/archive/poc-2026-05-20">historical proof of concept</a> is archived. Use the current source and these task guides for new work.</p></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};